INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (2295, 'math', 2, 'geometry', 'lines_angles_triangles', 'medium', 'In the triangle shown, what is the value of x?', NULL, '["45", "0", "1", "-1"]', 0, 'The correct answer is 45. An isosceles right triangle has a right angle and two legs of equal length. In the triangle shown, one angle is a right angle and the two legs each have a length of 15. Thus, the given triangle is an isosceles right triangle. In an isosceles right triangle, the measures of the two non-right angles are ° 45 . It follows that the value of x is 45.', 'This is a College Board practice test question. Review the official explanation for detailed analysis.', 'Work through more practice test questions in this section to build familiarity with the test format.', 1, 120, '["student_produced_response"]');
