INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (2298, 'math', 2, 'advanced_math', 'nonlinear_equations', 'hard', '[See practice test 11 PDF — Math Module 2, Question 20]', NULL, '["41/81", "0", "1", "-1"]', 0, 'The correct answer is 41/81. An expression of the form a^(m/n), where m and n are integers greater than 1 and a >= 0, is equivalent to the nth root of a^m. The expression on the left-hand side of the given equation is equivalent to p^(2/3); thus p^(2/3) = t^(9/7). If t = p^(3n-1), substituting yields the solution.', 'This is a College Board practice test question. Review the official explanation for detailed analysis.', 'Work through more practice test questions in this section to build familiarity with the test format.', 1, 150, '["student_produced_response", "figure_required"]');
